"""
Adapter contract validation and profile constants.

This module defines:
  - The canonical set of DEPLOYMENT_PROFILE values.
  - The canonical set of adapter port names.
  - Validation helpers that ensure a profile registry is complete
    (all ports wired) and that every adapter implements the correct port.

No business-logic forks by provider live here — only parity and validation rules.
"""

from __future__ import annotations

from typing import Any

from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)

# --- Canonical profile names ---------------------------------------------------

PROFILE_AWS = "aws"
PROFILE_ONPREM = "onprem"
VALID_PROFILES: frozenset[str] = frozenset({PROFILE_AWS, PROFILE_ONPREM})

# --- Canonical port names and their expected types -----------------------------

PORT_SPEC: dict[str, type] = {
    "object_storage": ObjectStoragePort,
    "queue": QueuePort,
    "eventing": EventingPort,
    "secrets": SecretsPort,
    "log_sink": LogSinkPort,
}


# --- Validation helpers --------------------------------------------------------

class AdapterContractError(Exception):
    """Raised when an adapter registry violates the adapter contract."""


def validate_profile(profile: str) -> str:
    """Return the normalised profile name or raise."""
    normalised = profile.strip().lower()
    if normalised not in VALID_PROFILES:
        raise AdapterContractError(
            f"Invalid DEPLOYMENT_PROFILE '{profile}'. "
            f"Valid profiles: {sorted(VALID_PROFILES)}"
        )
    return normalised


def validate_adapter_instance(port_name: str, adapter: Any) -> None:
    """Raise if *adapter* does not implement the port interface for *port_name*."""
    expected_type = PORT_SPEC.get(port_name)
    if expected_type is None:
        raise AdapterContractError(
            f"Unknown port name '{port_name}'. "
            f"Valid ports: {sorted(PORT_SPEC)}"
        )
    if not isinstance(adapter, expected_type):
        raise AdapterContractError(
            f"Adapter for port '{port_name}' must be an instance of "
            f"{expected_type.__name__}, got {type(adapter).__name__}"
        )


def validate_registry_completeness(adapters: dict[str, Any]) -> None:
    """Raise if any canonical port is missing from *adapters*."""
    missing = set(PORT_SPEC) - set(adapters)
    if missing:
        raise AdapterContractError(
            f"Adapter registry is incomplete. Missing ports: {sorted(missing)}"
        )
    for port_name, adapter in adapters.items():
        validate_adapter_instance(port_name, adapter)

