"""
AdapterRegistry — profile-aware adapter composition root.

Reads DEPLOYMENT_PROFILE from the environment (default: 'onprem') and
instantiates the matching adapter set.  Business code obtains adapters
exclusively through this registry; it never imports concrete adapter modules.
"""

from __future__ import annotations

import os
from typing import Any

from shared.adapters.adapter_contract import (
    PORT_SPEC,
    AdapterContractError,
    validate_adapter_instance,
    validate_profile,
    validate_registry_completeness,
)
from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)

_ENV_VAR = "DEPLOYMENT_PROFILE"
_DEFAULT_PROFILE = "onprem"


class AdapterRegistry:
    """
    Immutable adapter registry for a single deployment profile.

    Construction validates that every canonical port is present and that
    each adapter satisfies its port interface.
    """

    def __init__(self, profile: str, adapters: dict[str, Any]) -> None:
        self._profile = validate_profile(profile)
        validate_registry_completeness(adapters)
        self._adapters: dict[str, Any] = dict(adapters)

    # --- typed accessors -------------------------------------------------------

    @property
    def profile(self) -> str:
        return self._profile

    def object_storage(self) -> ObjectStoragePort:
        return self._adapters["object_storage"]

    def queue(self) -> QueuePort:
        return self._adapters["queue"]

    def eventing(self) -> EventingPort:
        return self._adapters["eventing"]

    def secrets(self) -> SecretsPort:
        return self._adapters["secrets"]

    def log_sink(self) -> LogSinkPort:
        return self._adapters["log_sink"]


# ---------------------------------------------------------------------------
# Profile → adapter factory mapping
# ---------------------------------------------------------------------------

def _build_aws_adapters(config: dict[str, Any] | None = None) -> dict[str, Any]:
    """Lazily import and instantiate AWS adapters."""
    from shared.adapters.aws.object_storage import S3ObjectStorage
    from shared.adapters.aws.queue import SQSQueue
    from shared.adapters.aws.eventing import SNSEventing
    from shared.adapters.aws.secrets import SecretsManagerSecrets
    from shared.adapters.aws.log_sink import CloudWatchLogSink

    cfg = config or {}
    return {
        "object_storage": S3ObjectStorage(
            endpoint_url=cfg.get("s3_endpoint_url"),
            region_name=cfg.get("region_name", "us-east-1"),
        ),
        "queue": SQSQueue(
            endpoint_url=cfg.get("sqs_endpoint_url"),
            region_name=cfg.get("region_name", "us-east-1"),
        ),
        "eventing": SNSEventing(
            endpoint_url=cfg.get("sns_endpoint_url"),
            region_name=cfg.get("region_name", "us-east-1"),
        ),
        "secrets": SecretsManagerSecrets(
            endpoint_url=cfg.get("secretsmanager_endpoint_url"),
            region_name=cfg.get("region_name", "us-east-1"),
        ),
        "log_sink": CloudWatchLogSink(
            endpoint_url=cfg.get("logs_endpoint_url"),
            region_name=cfg.get("region_name", "us-east-1"),
            log_group=cfg.get("log_group", "/app/default"),
            log_stream=cfg.get("log_stream", "default"),
        ),
    }


def _build_onprem_adapters(config: dict[str, Any] | None = None) -> dict[str, Any]:
    """Lazily import and instantiate on-prem adapters."""
    from shared.adapters.onprem.object_storage import MinioObjectStorage
    from shared.adapters.onprem.queue import RedisQueue
    from shared.adapters.onprem.eventing import RedisEventing
    from shared.adapters.onprem.secrets import FileSecrets
    from shared.adapters.onprem.log_sink import JsonFileLogSink

    cfg = config or {}
    return {
        "object_storage": MinioObjectStorage(
            endpoint_url=cfg.get("minio_endpoint_url", "http://localhost:9000"),
            access_key=cfg.get("minio_access_key", "minioadmin"),
            secret_key=cfg.get("minio_secret_key", "minioadmin"),
            secure=cfg.get("minio_secure", False),
        ),
        "queue": RedisQueue(
            redis_url=cfg.get("redis_url", "redis://localhost:6379/0"),
        ),
        "eventing": RedisEventing(
            redis_url=cfg.get("redis_url", "redis://localhost:6379/0"),
        ),
        "secrets": FileSecrets(
            secrets_dir=cfg.get("secrets_dir", "/run/secrets"),
        ),
        "log_sink": JsonFileLogSink(
            log_file=cfg.get("log_file", "/var/log/app/app.jsonl"),
        ),
    }


_PROFILE_FACTORIES: dict[str, Any] = {
    "aws": _build_aws_adapters,
    "onprem": _build_onprem_adapters,
}


def get_registry(
    profile: str | None = None,
    config: dict[str, Any] | None = None,
) -> AdapterRegistry:
    """
    Build an AdapterRegistry for the given profile.

    If *profile* is None, reads DEPLOYMENT_PROFILE from the environment
    (default 'onprem').
    """
    resolved = profile or os.environ.get(_ENV_VAR, _DEFAULT_PROFILE)
    resolved = validate_profile(resolved)

    factory = _PROFILE_FACTORIES.get(resolved)
    if factory is None:
        raise AdapterContractError(f"No adapter factory registered for profile '{resolved}'")

    adapters = factory(config)
    return AdapterRegistry(profile=resolved, adapters=adapters)

