"""MinIO adapter for ObjectStoragePort (on-prem profile)."""

from __future__ import annotations

import io

from minio import Minio
from minio.error import S3Error

from shared.adapters.ports import ObjectStoragePort


class MinioObjectStorage(ObjectStoragePort):
    """ObjectStoragePort backed by MinIO."""

    def __init__(
        self,
        endpoint_url: str = "http://localhost:9000",
        access_key: str = "minioadmin",
        secret_key: str = "minioadmin",
        secure: bool = False,
    ) -> None:
        # Strip scheme for minio client
        endpoint = endpoint_url
        if endpoint.startswith("http://"):
            endpoint = endpoint[len("http://"):]
            secure = False
        elif endpoint.startswith("https://"):
            endpoint = endpoint[len("https://"):]
            secure = True

        self._client = Minio(
            endpoint,
            access_key=access_key,
            secret_key=secret_key,
            secure=secure,
        )

    def _ensure_bucket(self, bucket: str) -> None:
        if not self._client.bucket_exists(bucket):
            self._client.make_bucket(bucket)

    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        self._ensure_bucket(bucket)
        self._client.put_object(
            bucket,
            key,
            io.BytesIO(data),
            length=len(data),
        )

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            response = self._client.get_object(bucket, key)
            return response.read()
        except S3Error as exc:
            if exc.code in ("NoSuchKey", "NoSuchBucket"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise
        finally:
            try:
                response.close()  # type: ignore[possibly-undefined]
                response.release_conn()  # type: ignore[possibly-undefined]
            except Exception:
                pass

    def delete_object(self, bucket: str, key: str) -> None:
        try:
            self._client.remove_object(bucket, key)
        except S3Error:
            pass

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        try:
            objects = self._client.list_objects(bucket, prefix=prefix)
            return [obj.object_name for obj in objects if obj.object_name]
        except S3Error:
            return []

