"""Redis-backed adapter for QueuePort (on-prem profile)."""

from __future__ import annotations

import json
import uuid
from typing import Any

import redis

from shared.adapters.ports import QueuePort


class RedisQueue(QueuePort):
    """QueuePort backed by Redis lists."""

    def __init__(self, redis_url: str = "redis://localhost:6379/0") -> None:
        self._redis = redis.Redis.from_url(redis_url, decode_responses=True)

    def send_message(
        self,
        queue_name: str,
        body: str,
        attributes: dict[str, str] | None = None,
    ) -> str:
        message_id = str(uuid.uuid4())
        envelope = json.dumps(
            {
                "message_id": message_id,
                "body": body,
                "attributes": attributes or {},
            }
        )
        self._redis.rpush(queue_name, envelope)
        return message_id

    def receive_messages(
        self,
        queue_name: str,
        max_messages: int = 1,
        wait_seconds: int = 0,
    ) -> list[dict[str, Any]]:
        results: list[dict[str, Any]] = []
        for _ in range(max_messages):
            if wait_seconds > 0:
                item = self._redis.blpop(queue_name, timeout=wait_seconds)
                raw = item[1] if item else None
            else:
                raw = self._redis.lpop(queue_name)
            if raw is None:
                break
            envelope = json.loads(raw)
            results.append(
                {
                    "message_id": envelope["message_id"],
                    "body": envelope["body"],
                    "receipt_handle": envelope["message_id"],
                }
            )
        return results

