"""File-based adapter for SecretsPort (on-prem profile)."""

from __future__ import annotations

import os

from shared.adapters.ports import SecretsPort


class FileSecrets(SecretsPort):
    """
    SecretsPort backed by files on disk.

    Each secret is stored as a file named <secret_id> inside *secrets_dir*.
    Compatible with Docker/Kubernetes secret volume mounts.
    """

    def __init__(self, secrets_dir: str = "/run/secrets") -> None:
        self._dir = secrets_dir

    def _path(self, secret_id: str) -> str:
        # Sanitise to prevent path traversal
        safe = secret_id.replace("/", "_").replace("..", "_")
        return os.path.join(self._dir, safe)

    def get_secret(self, secret_id: str) -> str:
        path = self._path(secret_id)
        if not os.path.isfile(path):
            raise KeyError(secret_id)
        with open(path, "r", encoding="utf-8") as fh:
            return fh.read().strip()

    def put_secret(self, secret_id: str, value: str) -> None:
        os.makedirs(self._dir, exist_ok=True)
        path = self._path(secret_id)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(value)

